ValidationRule.errorConditionFormula:
AND(
    OR(
        NOT(ISBLANK(GSTIN_Consignor__c)),
        NOT(ISBLANK(Consignee_GSTIN__c))
    ),
    OR(
        AND(
            NOT(ISBLANK(GSTIN_Consignor__c)),
            NOT(
                REGEX(
                    GSTIN_Consignor__c,
                    "^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$"
                )
            )
        ),
        AND(
            NOT(ISBLANK(Consignee_GSTIN__c)),
            NOT(
                REGEX(
                    Consignee_GSTIN__c,
                    "^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$"
                )
            )
        )
    )
)
